// Non-blocking enhancement for Game 2's existing (always-available)
// low-cost mountain texture maps. These image URLs are generated by
// tools/game2/bake-mountain-8k.mjs and deployed to public/game2/mountain8k.
// If the 8192² sources have NOT been baked/deployed, no false claim of
// 8K rendering is made: the engine retains its existing procedural fallback.
import { chooseMountainGpuResolution, GAME2_MOUNTAIN_8K_PATHS }
  from './trainingMountain8k.js';

function loadBitmap(url,signal){
  return new Promise((resolve,reject)=>{
    if(typeof Image==='undefined')return reject(new Error('Browser images unavailable'));
    if(signal?.aborted)return reject(new Error('Mountain asset load cancelled'));
    const image=new Image();
    let settled=false;
    const settle=(callback,value)=>{
      if(settled)return;
      settled=true;
      signal?.removeEventListener?.('abort',cancel);
      image.onload=null; image.onerror=null;
      callback(value);
    };
    const cancel=()=>{
      // Navigating away must not leave an 8192² decode/upload in flight
      // against an already-destroyed WebGL context.
      image.src='';
      settle(reject,new Error('Mountain asset load cancelled'));
    };
    image.onload=()=>settle(resolve,image);
    image.onerror=()=>settle(reject,new Error('8K mountain source missing: '+url));
    signal?.addEventListener?.('abort',cancel,{once:true});
    image.src=url;
  });
}
function scaleImage(image,size){
  if(size===image.width)return image;
  const canvas=document.createElement('canvas');
  canvas.width=size;canvas.height=size;
  const context=canvas.getContext('2d');
  if(!context)throw Error('2D downsample canvas unavailable');
  context.imageSmoothingEnabled=true;
  context.imageSmoothingQuality='high';
  context.drawImage(image,0,0,size,size);
  return canvas;
}
export function mountainTexturePlan(quality,maxTextureSize,deviceMemoryGb=0){
  // 4K is the established lightweight material preset. Never silently
  // download three 8192px images (50+ MB) when a player selects 4K.
  if(quality!=='8k')return null;
  if(maxTextureSize<4096)return null;
  return chooseMountainGpuResolution(quality,maxTextureSize,deviceMemoryGb);
}
/**
 * Load one baked map at a time. This avoids decoding 3×8192 textures at once
 * and caps the active GPU footprint to ~384 MiB on explicitly chosen 8K tier
 * (one rock 8192², moss/dirt 2048², all original source images are 8K).
 *
 * onMap receives a verified uploaded WebGL texture; callers can immediately
 * replace that kind while retaining fallback maps for the others.
 */
export async function streamGame2Mountain8kMaps(R,{quality,onMap,onStatus=()=>{},signal}={}){
  if(typeof document==='undefined'||!R?.gl||typeof R.uploadTexture!=='function')
    return {loaded:[],failed:[],resolution:null};
  const gl=R.gl,limit=Number(gl.getParameter(gl.MAX_TEXTURE_SIZE))||0;
  const memory=typeof navigator!=='undefined'?Number(navigator.deviceMemory)||0:0;
  const resolution=mountainTexturePlan(quality,limit,memory);
  if(!resolution)return {loaded:[],failed:[],resolution:null};
  const loaded=[],failed=[];
  for(const [kind,url] of Object.entries(GAME2_MOUNTAIN_8K_PATHS)){
    if(signal?.aborted||gl.isContextLost?.())break;
    try{
      const image=await loadBitmap(url,signal);
      if(signal?.aborted||gl.isContextLost?.())break;
      if(image.naturalWidth!==8192||image.naturalHeight!==8192)
        throw Error('Expected a real 8192 × 8192 baked '+kind+' source');
      const selected=scaleImage(image,resolution[kind]);
      if(signal?.aborted||gl.isContextLost?.())break;
      const texture=R.uploadTexture(selected,{anisotropy:8});
      const webglError=gl.getError?.();
      if(webglError && webglError!==gl.NO_ERROR){
        gl.deleteTexture?.(texture);
        throw Error('WebGL rejected '+resolution[kind]+'px '+kind+' source (error '+webglError+')');
      }
      if(signal?.aborted||gl.isContextLost?.()){
        gl.deleteTexture?.(texture);
        break;
      }
      // A WebGL allocation that silently failed must never replace
      // a working procedural fallback texture.
      if(gl.isTexture&&!gl.isTexture(texture)){
        gl.deleteTexture?.(texture);
        throw Error('GPU rejected '+resolution[kind]+'px '+kind+' texture');
      }
      onMap(kind,texture,resolution[kind]);
      loaded.push(kind);
      if(selected!==image){selected.width=0;selected.height=0;}
    }catch(error){
      if(signal?.aborted)break;
      failed.push({kind,reason:String(error?.message||error)});
    }
  }
  if(!signal?.aborted)onStatus({quality,loaded,failed,resolution});
  return {loaded,failed,resolution};
}
